window.RF_FULL=window.RF_FULL||{};window.RF_FULL["fz5485taina"]=[
["0","Преамбула и список изменений","","2024-08-08","ЗАКОН РОССИЙСКОЙ ФЕДЕРАЦИИ (Особенности применения настоящего Закона - федеральные законы от 05.04.2013 № 41-ФЗ, от 08.03.2022 № 46-ФЗ)\nО государственной тайне\nСписок изменяющих документов(В редакции федеральных законов от 06.10.1997 № 131-ФЗ, от 30.06.2003 № 86-ФЗ, от 11.11.2003 № 153-ФЗ, от 29.06.2004 № 58-ФЗ, от 22.08.2004 № 122-ФЗ, от 01.12.2007 № 294-ФЗ, от 01.12.2007 № 318-ФЗ, от 18.07.2009 № 180-ФЗ, от 15.11.2010 № 299-ФЗ, от 18.07.2011 № 242-ФЗ, от 19.07.2011 № 248-ФЗ, от 08.11.2011 № 309-ФЗ, от 21.12.2013 № 377-ФЗ, от 08.03.2015 № 23-ФЗ, от 26.07.2017 № 193-ФЗ, от 29.07.2018 № 256-ФЗ, от 30.12.2020 № 481-ФЗ, от 09.03.2021 № 39-ФЗ, от 11.06.2021 № 170-ФЗ, от 14.07.2022 № 292-ФЗ, от 04.08.2022 № 359-ФЗ, от 05.12.2022 № 498-ФЗ, от 04.08.2023 № 432-ФЗ, от 08.08.2024 № 249-ФЗ)\n(С учетом федеральных законов от 05.04.2013 № 41-ФЗ, от 08.03.2022 № 46-ФЗ)\nПреамбула. (Утратила силу - Федеральный закон от 04.08.2023 № 432-ФЗ)"],
["1","Сфера действия настоящего Закона","","2023-08-04","Статья 1. Сфера действия настоящего Закона\nНастоящий Закон регулирует отношения, связанные с отнесением сведений к государственной тайне, их засекречиванием или рассекречиванием и защитой государственной тайны в интересах обеспечения безопасности Российской Федерации.\n(Статья в редакции Федерального закона от 04.08.2023 № 432-ФЗ)"],
["2","Основные понятия, используемые в настоящем Законе","","2023-08-04","Статья 2. Основные понятия, используемые в настоящем Законе\nВ настоящем Законе используются следующие основные понятия:\nгосударственная тайна - защищаемые государством сведения, распространение которых может нанести ущерб безопасности Российской Федерации; (В редакции Федерального закона от 04.08.2023 № 432-ФЗ)\nносители сведений, составляющих государственную тайну, - материальные объекты, в том числе физические поля, в которых сведения, составляющие государственную тайну, находят свое отображение в виде символов, образов, сигналов, технических решений и процессов;\nсистема защиты государственной тайны - совокупность органов защиты государственной тайны, используемых ими средств и методов защиты сведений, составляющих государственную тайну, и их носителей, а также мероприятий, проводимых в этих целях;\nдопуск к государственной тайне - право лица на доступ к сведениям, составляющим государственную тайну, а предприятия, учреждения и организации - на проведение работ, связанных с использованием таких сведений, которое оформляется (переоформляется) в установленном порядке; (В редакции Федерального закона от 04.08.2023 № 432-ФЗ)\nдоступ к сведениям, составляющим государственную тайну, - санкционированное полномочным должностным лицом ознакомление конкретного лица со сведениями, составляющими государственную тайну;\nгриф секретности - реквизиты, свидетельствующие о степени секретности сведений, содержащихся в их носителе, проставляемые на самом носителе и (или) в сопроводительной документации на него;\nсредства защиты информации - технические, криптографические, программные и другие средства, предназначенные для защиты сведений, составляющих государственную тайну, средства, в которых они реализованы, а также средства контроля эффективности защиты информации;\nрежим секретности - совокупность требований, правил, организационных, технических и иных мер, направленных на защиту сведений, составляющих государственную тайну; (Дополнение абзацем - Федеральный закон от 04.08.2023 № 432-ФЗ)\nПеречень сведений, составляющих государственную тайну, - совокупность категорий сведений, в соответствии с которыми сведения относятся к государственной тайне и засекречиваются на основаниях и в порядке, установленных федеральным законодательством. (Дополнение абзацем - Федеральный закон от 06.10.1997 № 131-ФЗ)"],
["3","Законодательство Российской Федерации о государственной тайне","","2023-08-04","Статья 3. Законодательство Российской Федерации о государственной тайне\nЗаконодательство Российской Федерации о государственной тайне основывается на Конституции Российской Федерации и включает в себя настоящий Закон, федеральные законы, регулирующие отношения, связанные с защитой государственной тайны, а также принимаемые в соответствии с ними иные нормативные правовые акты Российской Федерации.\n(Статья в редакции Федерального закона от 04.08.2023 № 432-ФЗ)"],
["4","Полномочия органов государственной власти и должностных лиц в области отнесения сведений к государственной тайне и их защиты","","2024-08-08","Статья 4. Полномочия органов государственной власти и должностных лиц в области отнесения сведений к государственной тайне и их защиты\n1. Палаты Федерального Собрания: (В редакции Федерального закона от 06.10.1997 № 131-ФЗ)\nосуществляют законодательное регулирование отношений в области государственной тайны; (В редакции Федерального закона от 06.10.1997 № 131-ФЗ)\nрассматривают статьи федерального бюджета в части средств, направляемых на реализацию государственных программ в области защиты государственной тайны; (В редакции Федерального закона от 06.10.1997 № 131-ФЗ)\nабзац; (Исключен - Федеральный закон от 06.10.1997 № 131-ФЗ)\nопределяют полномочия должностных лиц в аппаратах палат Федерального Собрания по обеспечению защиты государственной тайны в палатах Федерального Собрания; (В редакции Федерального закона от 06.10.1997 № 131-ФЗ)\nабзац. (Исключен - Федеральный закон от 06.10.1997 № 131-ФЗ)\n2. Президент Российской Федерации:\nутверждает государственные программы в области защиты государственной тайны;\nутверждает по представлению Правительства Российской Федерации состав, структуру межведомственной комиссии по защите государственной тайны и положение о ней;\nутверждает по представлению Правительства Российской Федерации Перечень должностных лиц органов государственной власти и организаций, наделяемых полномочиями по отнесению сведений к государственной тайне, Перечень должностей, при замещении которых лица считаются допущенными к государственной тайне, а также Перечень сведений, отнесенных к государственной тайне; (В редакции Федерального закона от 18.07.2009 № 180-ФЗ)\nзаключает международные договоры Российской Федерации о совместном использовании и защите сведений, составляющих государственную тайну;\nопределяет полномочия должностных лиц по обеспечению защиты государственной тайны и порядок обеспечения режима секретности в Администрации Президента Российской Федерации, включая вопросы оформления, переоформления и прекращения допуска должностных лиц к государственной тайне, доступа к сведениям, составляющим государственную тайну, в Администрации Президента Российской Федерации, а также вопросы выезда из Российской Федерации работников Администрации Президента Российской Федерации, допущенных или ранее допускавшихся к государственной тайне; (В редакции Федерального закона от 04.08.2023 № 432-ФЗ)\nв пределах своих полномочий решает иные вопросы, возникающие в связи с отнесением сведений к государственной тайне, их засекречиванием или рассекречиванием и их защитой. (В редакции Федерального закона от 06.10.1997 № 131-ФЗ)\n3. Правительство Российской Федерации:\nорганизует исполнение Закона Российской Федерации \"О государственной тайне\";\nпредставляет на утверждение Президенту Российской Федерации состав, структуру межведомственной комиссии по защите государственной тайны и положение о ней;\nпредставляет на утверждение Президенту Российской Федерации Перечень должностных лиц органов государственной власти и организаций, наделяемых полномочиями по отнесению сведений к государственной тайне, Перечень должностей, при замещении которых лица считаются допущенными к государственной тайне, а также Перечень сведений, отнесенных к государственной тайне; (В редакции Федерального закона от 18.07.2009 № 180-ФЗ)\nустанавливает порядок разработки Перечня сведений, отнесенных к государственной тайне;\nорганизует разработку и выполнение государственных программ в области защиты государственной тайны;\nопределяет полномочия должностных лиц по обеспечению защиты государственной тайны в аппарате Правительства Российской Федерации;\nустанавливает порядок предоставления социальных гарантий гражданам, допущенным к государственной тайне на постоянной основе, и сотрудникам структурных подразделений по защите государственной тайны, если социальные гарантии либо порядок предоставления таких социальных гарантий не установлены федеральными законами или нормативными правовыми актами Президента Российской Федерации; (В редакции федеральных законов от 22.08.2004 № 122-ФЗ; от 08.11.2011 № 309-ФЗ)\nустанавливает порядок определения размеров ущерба, наступившего в результате несанкционированного распространения сведений, составляющих государственную тайну, а также ущерба, наносимого собственнику информации в результате ее засекречивания;\nзаключает межправительственные соглашения, принимает меры по выполнению международных договоров Российской Федерации о совместном использовании и защите сведений, составляющих государственную тайну, принимает решения о возможности передачи их носителей другим государствам или международным организациям; (В редакции Федерального закона от 01.12.2007 № 294-ФЗ)\nустанавливает порядок оформления, переоформления и прекращения допуска должностных лиц и граждан Российской Федерации, в том числе имеющих гражданство (подданство) иностранного государства, лиц без гражданства, иностранных граждан к государственной тайне, а также их доступа к сведениям, составляющим государственную тайну; (Дополнение абзацем - Федеральный закон от 04.08.2023 № 432-ФЗ)\nустанавливает порядок обеспечения режима секретности в Российской Федерации; (Дополнение абзацем - Федеральный закон от 04.08.2023 № 432-ФЗ)\nиздает акты по вопросам, связанным с выездом из Российской Федерации граждан Российской Федерации, допущенных или ранее допускавшихся к государственной тайне; (Дополнение абзацем - Федеральный закон от 04.08.2023 № 432-ФЗ)\nустанавливает порядок организации и проведения работ по противодействию иностранным техническим разведкам и технической защите информации, содержащей сведения, составляющие государственную тайну; (Дополнение абзацем - Федеральный закон от 04.08.2023 № 432-ФЗ)\nв пределах своих полномочий решает иные вопросы, возникающие в связи с отнесением сведений к государственной тайне, их засекречиванием или рассекречиванием и их защитой. (Дополнение абзацем - Федеральный закон от 06.10.1997 № 131-ФЗ)\n4. Органы государственной власти Российской Федерации, органы государственной власти субъектов Российской Федерации, иные государственные органы, организации, наделенные в соответствии с федеральным законом полномочиями осуществлять от имени Российской Федерации государственное управление в установленной сфере деятельности (далее - органы государственной власти), органы публичной власти федеральных территорий и органы местного самоуправления во взаимодействии с органами защиты государственной тайны: (В редакции Федерального закона от 04.08.2023 № 432-ФЗ)\nобеспечивают защиту переданных им другими органами государственной власти, предприятиями, учреждениями и организациями сведений, составляющих государственную тайну, а также сведений, засекречиваемых ими;\nобеспечивают защиту государственной тайны на подведомственных им предприятиях, в учреждениях и организациях в соответствии с требованиями актов законодательства Российской Федерации;\nустанавливают размеры предоставляемых социальных гарантий гражданам, допущенным к государственной тайне на постоянной основе, и сотрудникам структурных подразделений по защите государственной тайны на подведомственных им предприятиях, в учреждениях и организациях;\nобеспечивают в пределах своей компетенции проведение проверочных мероприятий в отношении граждан, допускаемых к государственной тайне;\nреализуют предусмотренные законодательством меры по ограничению прав граждан и предоставлению социальных гарантий лицам, имеющим либо имевшим доступ к сведениям, составляющим государственную тайну;\nвносят в полномочные органы государственной власти предложения по совершенствованию системы защиты государственной тайны.\n(Пункт в редакции Федерального закона от 22.08.2004 № 122-ФЗ)\n4.1. Органы государственной власти, наделенные в соответствии с настоящим Законом полномочиями по распоряжению сведениями, отнесенными к государственной тайне, могут в части, не противоречащей настоящему Закону, нормативным правовым актам Президента Российской Федерации и Правительства Российской Федерации в области защиты государственной тайны, устанавливать в указанных органах государственной власти и подведомственных им органах и организациях порядок оформления, переоформления и прекращения допуска граждан к государственной тайне, а также их доступа к сведениям, составляющим государственную тайну, учитывающий специфику решаемых ими задач, по согласованию с федеральным органом исполнительной власти, уполномоченным в области обеспечения безопасности. (Дополнение пунктом - Федеральный закон от 08.08.2024 № 249-ФЗ)\n5. Органы судебной власти:\nрассматривают уголовные, гражданские и административные дела о нарушениях законодательства Российской Федерации о государственной тайне; (В редакции Федерального закона от 08.03.2015 № 23-ФЗ)\nобеспечивают судебную защиту граждан, органов государственной власти, предприятий, учреждений и организаций в связи с их деятельностью по защите государственной тайны;\nобеспечивают в ходе рассмотрения указанных дел защиту государственной тайны;\nопределяют полномочия должностных лиц по обеспечению защиты государственной тайны в органах судебной власти."],
["5","Перечень сведений, составляющих государственную тайну","","2023-08-04","Статья 5. Перечень сведений, составляющих государственную тайну\nГосударственную тайну составляют:\n1) сведения в военной области:\nо содержании стратегических и оперативных планов, документов боевого управления по подготовке и проведению операций, стратегическому, оперативному и мобилизационному развертыванию Вооруженных Сил Российской Федерации, других войск, воинских формирований и органов, предусмотренных Федеральным законом \"Об обороне\", об их боевой и мобилизационной готовности, о создании и об использовании мобилизационных ресурсов;\nо планах строительства Вооруженных Сил Российской Федерации, других войск Российской Федерации, о направлениях развития вооружения и военной техники, о содержании и результатах выполнения целевых программ, научно-исследовательских и опытно-конструкторских работ по созданию и модернизации образцов вооружения и военной техники;\nо разработке, технологии, производстве, об объемах производства, о хранении, об утилизации ядерных боеприпасов, их составных частей, делящихся ядерных материалов, используемых в ядерных боеприпасах, о технических средствах и (или) методах защиты ядерных боеприпасов от несанкционированного применения, а также о ядерных энергетических и специальных физических установках оборонного значения;\nо тактико-технических характеристиках и возможностях боевого применения образцов вооружения и военной техники, о свойствах, рецептурах или технологиях производства новых видов ракетного топлива или взрывчатых веществ военного назначения;\nо дислокации, назначении, степени готовности, защищенности режимных и особо важных объектов, об их проектировании, строительстве и эксплуатации, а также об отводе земель, недр и акваторий для этих объектов;\nо дислокации, действительных наименованиях, об организационной структуре, о вооружении, численности войск и состоянии их боевого обеспечения, а также о военно-политической и (или) оперативной обстановке;\n2) сведения в области экономики, науки и техники:\nо содержании планов подготовки Российской Федерации и ее отдельных регионов к возможным военным действиям, о мобилизационных мощностях промышленности по изготовлению и ремонту вооружения и военной техники, об объемах производства, поставок, о запасах стратегических видов сырья и материалов, а также о размещении, фактических размерах и об использовании государственных материальных резервов;\nоб использовании инфраструктуры Российской Федерации в целях обеспечения обороноспособности и безопасности государства;\nо силах и средствах гражданской обороны, о дислокации, предназначении и степени защищенности объектов административного управления, о степени обеспечения безопасности населения, о функционировании транспорта и связи в Российской Федерации в целях обеспечения безопасности государства;\nоб объемах, о планах (заданиях) государственного оборонного заказа, о выпуске и поставках (в денежном или натуральном выражении) вооружения, военной техники и другой оборонной продукции, о наличии и наращивании мощностей по их выпуску, о связях предприятий по кооперации, о разработчиках или об изготовителях указанных вооружения, военной техники и другой оборонной продукции;\nо достижениях науки и техники, о научно-исследовательских, об опытно-конструкторских, о проектных работах и технологиях, имеющих важное оборонное или экономическое значение, влияющих на безопасность государства;\nо запасах платины, металлов платиновой группы, природных алмазов в Государственном фонде драгоценных металлов и драгоценных камней Российской Федерации, Центральном банке Российской Федерации, а также об объемах запасов в недрах, добычи, производства и потребления стратегических видов полезных ископаемых Российской Федерации (по списку, определяемому Правительством Российской Федерации); (В редакции Федерального закона от 11.11.2003 № 153-ФЗ)\n3) сведения в области внешней политики и экономики:\nо внешнеполитической, внешнеэкономической деятельности Российской Федерации, преждевременное распространение которых может нанести ущерб безопасности государства;\nо финансовой политике в отношении иностранных государств (за исключением обобщенных показателей по внешней задолженности), а также о финансовой или денежно-кредитной деятельности, преждевременное распространение которых может нанести ущерб безопасности государства;\n4) сведения в области разведывательной, контрразведывательной и оперативно-розыскной деятельности, а также в области противодействия терроризму и в области обеспечения безопасности лиц, в отношении которых принято решение о применении мер государственной защиты: (В редакции федеральных законов от 15.11.2010 № 299-ФЗ; от 21.12.2013 № 377-ФЗ)\nо силах, средствах, об источниках, о методах, планах и результатах разведывательной, контрразведывательной, оперативно-розыскной деятельности и деятельности по противодействию терроризму, а также данные о финансировании этой деятельности, если эти данные раскрывают перечисленные сведения; (В редакции Федерального закона от 15.11.2010 № 299-ФЗ)\nо силах, средствах, об источниках, о методах, планах и результатах деятельности по обеспечению безопасности лиц, в отношении которых принято решение о применении мер государственной защиты, данные о финансировании этой деятельности, если эти данные раскрывают перечисленные сведения, а также отдельные сведения об указанных лицах; (Дополнение абзацем - Федеральный закон от 21.12.2013 № 377-ФЗ)\nо лицах, сотрудничающих или сотрудничавших на конфиденциальной основе с органами, осуществляющими разведывательную, контрразведывательную и оперативно-розыскную деятельность;\nоб организации, о силах, средствах и методах обеспечения безопасности объектов государственной охраны, а также данные о финансировании этой деятельности, если эти данные раскрывают перечисленные сведения;\nо системе президентской, правительственной, шифрованной, в том числе кодированной и засекреченной связи, о шифрах, о разработке, об изготовлении шифров и обеспечении ими, о методах и средствах анализа шифровальных средств и средств специальной защиты, об информационно-аналитических системах специального назначения;\nо методах и средствах защиты секретной информации;\nоб организации обеспечения режима секретности и о фактическом состоянии защиты государственной тайны; (В редакции Федерального закона от 04.08.2023 № 432-ФЗ)\nо защите Государственной границы Российской Федерации, исключительной экономической зоны и континентального шельфа Российской Федерации;\nо расходах федерального бюджета, связанных с обеспечением обороны, безопасности государства и правоохранительной деятельности в Российской Федерации;\nо подготовке кадров, раскрывающие мероприятия, проводимые в целях обеспечения безопасности государства;\nо мерах по обеспечению защищенности критически важных объектов и потенциально опасных объектов инфраструктуры Российской Федерации от террористических актов; (Дополнение абзацем - Федеральный закон от 15.11.2010 № 299-ФЗ)\nо результатах финансового мониторинга в отношении организаций и физических лиц, полученных в связи с проверкой их возможной причастности к террористической деятельности; (Дополнение абзацем - Федеральный закон от 15.11.2010 № 299-ФЗ)\nо мерах по обеспечению безопасности критической информационной инфраструктуры Российской Федерации и о состоянии ее защищенности от компьютерных атак. (Дополнение абзацем - Федеральный закон от 26.07.2017 № 193-ФЗ)\n(Статья в редакции Федерального закона от 06.10.1997 № 131-ФЗ)"],
["6","Принципы отнесения сведений к государственной тайне и засекречивания этих сведений","","1997-10-06","Статья 6. Принципы отнесения сведений к государственной тайне и засекречивания этих сведений\n(Наименование в редакции Федерального закона от 06.10.1997 № 131-ФЗ)\nОтнесение сведений к государственной тайне и их засекречивание - введение в предусмотренном настоящим Законом порядке для сведений, составляющих государственную тайну, ограничений на их распространение и на доступ к их носителям. (В редакции Федерального закона от 06.10.1997 № 131-ФЗ)\nОтнесение сведений к государственной тайне и их засекречивание осуществляется в соответствии с принципами законности, обоснованности и своевременности. (В редакции Федерального закона от 06.10.1997 № 131-ФЗ)\nЗаконность отнесения сведений к государственной тайне и их засекречивание заключается в соответствии засекречиваемых сведений положениям статей 5 и 7 настоящего Закона и законодательству Российской Федерации о государственной тайне. (В редакции Федерального закона от 06.10.1997 № 131-ФЗ)\nОбоснованность отнесения сведений к государственной тайне и их засекречивание заключается в установлении путем экспертной оценки целесообразности засекречивания конкретных сведений, вероятных экономических и иных последствий этого акта исходя из баланса жизненно важных интересов государства, общества и граждан. (В редакции Федерального закона от 06.10.1997 № 131-ФЗ)\nСвоевременность отнесения сведений к государственной тайне и их засекречивание заключается в установлении ограничений на распространение этих сведений с момента их получения (разработки) или заблаговременно. (В редакции Федерального закона от 06.10.1997 № 131-ФЗ)"],
["7","Сведения, не подлежащие отнесению к государственной тайне и засекречиванию","","2022-07-14","Статья 7. Сведения, не подлежащие отнесению к государственной тайне и засекречиванию\n(Наименование в редакции Федерального закона от 06.10.1997 № 131-ФЗ)\nНе подлежат отнесению к государственной тайне и засекречиванию сведения: (В редакции Федерального закона от 06.10.1997 № 131-ФЗ)\nо чрезвычайных происшествиях и катастрофах, угрожающих безопасности и здоровью граждан, и их последствиях, а также о стихийных бедствиях, их официальных прогнозах и последствиях;\nо состоянии здравоохранения, санитарии, демографии, образования, культуры, сельского хозяйства, а также о состоянии преступности; (В редакции Федерального закона от 09.03.2021 № 39-ФЗ)\nо привилегиях, компенсациях и социальных гарантиях, предоставляемых государством гражданам, должностным лицам, предприятиям, учреждениям и организациям; (В редакции Федерального закона от 22.08.2004 № 122-ФЗ)\nо фактах нарушения прав и свобод человека и гражданина;\nабзац; (Утратил силу - Федеральный закон от 14.07.2022 № 292-ФЗ)\nо состоянии здоровья высших должностных лиц Российской Федерации;\nо фактах нарушения законности органами государственной власти и их должностными лицами;\nсоставляющие информацию о состоянии окружающей среды (экологическую информацию). (Дополнение абзацем - Федеральный закон от 09.03.2021 № 39-ФЗ)\nДолжностные лица, принявшие решения о засекречивании перечисленных сведений либо о включении их в этих целях в носители сведений, составляющих государственную тайну, несут уголовную, административную или дисциплинарную ответственность в зависимости от причиненного обществу, государству и гражданам материального и морального ущерба. Граждане вправе обжаловать такие решения в суд."],
["8","Степени секретности сведений и грифы секретности носителей этих сведений","","","Статья 8. Степени секретности сведений и грифы секретности носителей этих сведений\nСтепень секретности сведений, составляющих государственную тайну, должна соответствовать степени тяжести ущерба, который может быть нанесен безопасности Российской Федерации вследствие распространения указанных сведений.\nУстанавливаются три степени секретности сведений, составляющих государственную тайну, и соответствующие этим степеням грифы секретности для носителей указанных сведений: \"особой важности\", \"совершенно секретно\" и \"секретно\".\nПорядок определения размеров ущерба, который может быть нанесен безопасности Российской Федерации вследствие распространения сведений, составляющих государственную тайну, и правила отнесения указанных сведений к той или иной степени секретности устанавливаются Правительством Российской Федерации.\nИспользование перечисленных грифов секретности для засекречивания сведений, не отнесенных к государственной тайне, не допускается."],
["9","Порядок отнесения сведений к государственной тайне","","1997-10-06","Статья 9. Порядок отнесения сведений к государственной тайне\nОтнесение сведений к государственной тайне осуществляется в соответствии с их отраслевой, ведомственной или программно-целевой принадлежностью, а также в соответствии с настоящим Законом. (В редакции Федерального закона от 06.10.1997 № 131-ФЗ)\nОбоснование необходимости отнесения сведений к государственной тайне в соответствии с принципами засекречивания сведений возлагается на органы государственной власти, предприятия, учреждения и организации, которыми эти сведения получены (разработаны).\nОтнесение сведений к государственной тайне осуществляется в соответствии с Перечнем сведений, составляющих государственную тайну, определяемым настоящим Законом, руководителями органов государственной власти в соответствии с Перечнем должностных лиц, наделенных полномочиями по отнесению сведений к государственной тайне, утверждаемым Президентом Российской Федерации. Указанные лица несут персональную ответственность за принятые ими решения о целесообразности отнесения конкретных сведений к государственной тайне. (В редакции Федерального закона от 06.10.1997 № 131-ФЗ)\nДля осуществления единой государственной политики в области засекречивания сведений межведомственная комиссия по защите государственной тайны формирует по предложениям органов государственной власти и в соответствии с Перечнем сведений, составляющих государственную тайну, Перечень сведений, отнесенных к государственной тайне. В этом Перечне указываются органы государственной власти, наделяемые полномочиями по распоряжению данными сведениями. Указанный Перечень утверждается Президентом Российской Федерации, подлежит открытому опубликованию и пересматривается по мере необходимости. (В редакции Федерального закона от 06.10.1997 № 131-ФЗ)\nОрганами государственной власти, руководители которых наделены полномочиями по отнесению сведений к государственной тайне, в соответствии с Перечнем сведений, отнесенных к государственной тайне, разрабатываются развернутые перечни сведений, подлежащих засекречиванию. В эти перечни включаются сведения, полномочиями по распоряжению которыми наделены указанные органы, и устанавливается степень их секретности. В рамках целевых программ по разработке и модернизации образцов вооружения и военной техники, опытно-конструкторских и научно-исследовательских работ по решению заказчиков указанных образцов и работ могут разрабатываться отдельные перечни сведений, подлежащих засекречиванию. Эти перечни утверждаются соответствующими руководителями органов государственной власти. Целесообразность засекречивания таких перечней определяется их содержанием. (В редакции Федерального закона от 06.10.1997 № 131-ФЗ)"],
["10","Ограничение прав собственности предприятий, учреждений, организаций и граждан Российской Федерации на информацию в связи с ее засекречиванием","","","Статья 10. Ограничение прав собственности предприятий, учреждений, организаций и граждан Российской Федерации на информацию в связи с ее засекречиванием\nДолжностные лица, наделенные в порядке, предусмотренном статьей 9 настоящего Закона, полномочиями по отнесению сведений к государственной тайне, вправе принимать решения о засекречивании информации, находящейся в собственности предприятий, учреждений, организаций и граждан (далее - собственник информации), если эта информация включает сведения, перечисленные в Перечне сведений, отнесенных к государственной тайне. Засекречивание указанной информации осуществляется по представлению собственников информации или соответствующих органов государственной власти.\nМатериальный ущерб, наносимый собственнику информации в связи с ее засекречиванием, возмещается государством в размерах, определяемых в договоре между органом государственной власти, в распоряжение которого переходит эта информация, и ее собственником. В договоре также предусматриваются обязательства собственника информации по ее нераспространению. При отказе собственника информации от подписания договора он предупреждается об ответственности за несанкционированное распространение сведений, составляющих государственную тайну, в соответствии с действующим законодательством.\nСобственник информации вправе обжаловать в суд действия должностных лиц, ущемляющие, по мнению собственника информации, его права. В случае признания судом действий должностных лиц незаконными порядок возмещения ущерба, нанесенного собственнику информации, определяется решением суда в соответствии с действующим законодательством.\nНе может быть ограничено право собственности на информацию иностранных организаций и иностранных граждан, если эта информация получена (разработана) ими без нарушения законодательства Российской Федерации."],
["11","Порядок засекречивания сведений и их носителей","","","Статья 11. Порядок засекречивания сведений и их носителей\nОснованием для засекречивания сведений, полученных (разработанных) в результате управленческой, производственной, научной и иных видов деятельности органов государственной власти, предприятий, учреждений и организаций, является их соответствие действующим в данных органах, на данных предприятиях, в данных учреждениях и организациях перечням сведений, подлежащих засекречиванию. При засекречивании этих сведений их носителям присваивается соответствующий гриф секретности.\nПри невозможности идентификации полученных (разработанных) сведений со сведениями, содержащимися в действующем перечне, должностные лица органов государственной власти, предприятий, учреждений и организаций обязаны обеспечить предварительное засекречивание полученных (разработанных) сведений в соответствии с предполагаемой степенью секретности и в месячный срок направить в адрес должностного лица, утвердившего указанный перечень, предложения по его дополнению (изменению).\nДолжностные лица, утвердившие действующий перечень, обязаны в течение трех месяцев организовать экспертную оценку поступивших предложений и принять решение по дополнению (изменению) действующего перечня или снятию предварительно присвоенного сведениям грифа секретности."],
["12","Реквизиты носителей сведений, составляющих государственную тайну","","","Статья 12. Реквизиты носителей сведений, составляющих государственную тайну\nНа носители сведений, составляющих государственную тайну, наносятся реквизиты, включающие следующие данные:\nо степени секретности содержащихся в носителе сведений со ссылкой на соответствующий пункт действующего в данном органе государственной власти, на данном предприятии, в данных учреждении и организации перечня сведений, подлежащих засекречиванию;\nоб органе государственной власти, о предприятии, об учреждении, организации, осуществивших засекречивание носителя;\nо регистрационном номере;\nо дате или условии рассекречивания сведений либо о событии, после наступления которого сведения будут рассекречены.\nПри невозможности нанесения таких реквизитов на носитель сведений, составляющих государственную тайну, эти данные указываются в сопроводительной документации на этот носитель.\nЕсли носитель содержит составные части с различными степенями секретности, каждой из этих составных частей присваивается соответствующий гриф секретности, а носителю в целом присваивается гриф секретности, соответствующий тому грифу секретности, который присваивается его составной части, имеющей высшую для данного носителя степень секретности сведений.\nПомимо перечисленных в настоящей статье реквизитов на носителе и (или) в сопроводительной документации к нему могут проставляться дополнительные отметки, определяющие полномочия должностных лиц по ознакомлению с содержащимися в этом носителе сведениями. Вид и порядок проставления дополнительных отметок и других реквизитов определяются нормативными документами, утверждаемыми Правительством Российской Федерации."],
["13","Порядок рассекречивания сведений","","","Статья 13. Порядок рассекречивания сведений\nРассекречивание сведений и их носителей - снятие ранее введенных в предусмотренном настоящим Законом порядке ограничений на распространение сведений, составляющих государственную тайну, и на доступ к их носителям.\nОснованиями для рассекречивания сведений являются:\nвзятие на себя Российской Федерацией международных обязательств по открытому обмену сведениями, составляющими в Российской Федерации государственную тайну;\nизменение объективных обстоятельств, вследствие которого дальнейшая защита сведений, составляющих государственную тайну, является нецелесообразной.\nОрганы государственной власти, руководители которых наделены полномочиями по отнесению сведений к государственной тайне, обязаны периодически, но не реже чем через каждые 5 лет, пересматривать содержание действующих в органах государственной власти, на предприятиях, в учреждениях и организациях перечней сведений, подлежащих засекречиванию, в части обоснованности засекречивания сведений и их соответствия установленной ранее степени секретности.\nСрок засекречивания сведений, составляющих государственную тайну, не должен превышать 30 лет. В исключительных случаях этот срок может быть продлен по заключению межведомственной комиссии по защите государственной тайны.\nПравом изменения действующих в органах государственной власти, на предприятиях, в учреждениях и организациях перечней сведений, подлежащих засекречиванию, наделяются утвердившие их руководители органов государственной власти, которые несут персональную ответственность за обоснованность принятых ими решений по рассекречиванию сведений. Решения указанных руководителей, связанные с изменением перечня сведений, отнесенных к государственной тайне, подлежат согласованию с межведомственной комиссией по защите государственной тайны, которая вправе приостанавливать и опротестовывать эти решения."],
["14","Порядок рассекречивания носителей сведений, составляющих государственную тайну","","","Статья 14. Порядок рассекречивания носителей сведений, составляющих государственную тайну\nНосители сведений, составляющих государственную тайну, рассекречиваются не позднее сроков, установленных при их засекречивании. До истечения этих сроков носители подлежат рассекречиванию, если изменены положения действующего в данном органе государственной власти, на предприятии, в учреждении и организации перечня, на основании которых они были засекречены.\nВ исключительных случаях право продления первоначально установленных сроков засекречивания носителей сведений, составляющих государственную тайну, предоставляется руководителям государственных органов, наделенным полномочиями по отнесению соответствующих сведений к государственной тайне, на основании заключения назначенной ими в установленном порядке экспертной комиссии.\nРуководители органов государственной власти, предприятий, учреждений и организаций наделяются полномочиями по рассекречиванию носителей сведений, необоснованно засекреченных подчиненными им должностными лицами.\nРуководители государственных архивов Российской Федерации наделяются полномочиями по рассекречиванию носителей сведений, составляющих государственную тайну, находящихся на хранении в закрытых фондах этих архивов, в случае делегирования им таких полномочий организацией-фондообразователем или ее правопреемником. В случае ликвидации организации-фондообразователя и отсутствия ее правопреемника вопрос о порядке рассекречивания носителей сведений, составляющих государственную тайну, рассматривается межведомственной комиссией по защите государственной тайны."],
["15","Исполнение запросов граждан, предприятий, учреждений, организаций и органов государственной власти Российской Федерации о рассекречивании сведений","","","Статья 15. Исполнение запросов граждан, предприятий, учреждений, организаций и органов государственной власти Российской Федерации о рассекречивании сведений\nГраждане, предприятия, учреждения, организации и органы государственной власти Российской Федерации вправе обратиться в органы государственной власти, на предприятия, в учреждения, организации, в том числе в государственные архивы, с запросом о рассекречивании сведений, отнесенных к государственной тайне.\nОрганы государственной власти, предприятия, учреждения, организации, в том числе государственные архивы, получившие такой запрос, обязаны в течение трех месяцев рассмотреть его и дать мотивированный ответ по существу запроса. Если они не правомочны решить вопрос о рассекречивании запрашиваемых сведений, то запрос в месячный срок с момента его поступления передается в орган государственной власти, наделенный такими полномочиями, либо в межведомственную комиссию по защите государственной тайны, о чем уведомляются граждане, предприятия, учреждения, организации и органы государственной власти Российской Федерации, подавшие запрос.\nУклонение должностных лиц от рассмотрения запроса по существу влечет за собой административную (дисциплинарную) ответственность в соответствии с действующим законодательством.\nОбоснованность отнесения сведений к государственной тайне может быть обжалована в суд. При признании судом необоснованности засекречивания сведений эти сведения подлежат рассекречиванию в установленном настоящим Законом порядке."],
["16","Взаимная передача сведений, составляющих государственную тайну, органами государственной власти, предприятиями, учреждениями и организациями","","","Статья 16. Взаимная передача сведений, составляющих государственную тайну, органами государственной власти, предприятиями, учреждениями и организациями\nВзаимная передача сведений, составляющих государственную тайну, осуществляется органами государственной власти, предприятиями, учреждениями и организациями, не состоящими в отношениях подчиненности и не выполняющими совместных работ, с санкции органа государственной власти, в распоряжении которого в соответствии со статьей 9 настоящего Закона находятся эти сведения.\nОрганы государственной власти, предприятия, учреждения и организации, запрашивающие сведения, составляющие государственную тайну, обязаны создать условия, обеспечивающие защиту этих сведений. Их руководители несут персональную ответственность за несоблюдение установленных ограничений по ознакомлению со сведениями, составляющими государственную тайну.\nОбязательным условием для передачи сведений, составляющих государственную тайну, органам государственной власти, предприятиям, учреждениям и организациям является выполнение ими требований, предусмотренных в статье 27 настоящего Закона."],
["17","Передача сведений, составляющих государственную тайну, в связи с выполнением совместных и других работ","","2023-08-04","Статья 17. Передача сведений, составляющих государственную тайну, в связи с выполнением совместных и других работ\nПередача сведений, составляющих государственную тайну, предприятиям, учреждениям, организациям или гражданам в связи с выполнением совместных и других работ осуществляется заказчиком этих работ с разрешения органа государственной власти, в распоряжении которого в соответствии со статьей 9 настоящего Закона находятся соответствующие сведения, и только в объеме, необходимом для выполнения этих работ. При этом до передачи сведений, составляющих государственную тайну, заказчик обязан убедиться в наличии у предприятия, учреждения или организации лицензии на проведение работ с использованием сведений соответствующей степени секретности, а у граждан - соответствующего допуска.\nПредприятия, учреждения или организации при проведении совместных и других работ и возникновении в связи с этим необходимости в использовании сведений, составляющих государственную тайну, могут в целях получения доступа к таким сведениям заключать с органами государственной власти, органами местного самоуправления, органами публичной власти федеральных территорий, предприятиями, учреждениями или организациями, являющимися заказчиками этих работ, договоры об использовании (на период проведения работ) услуг их структурных подразделений по защите государственной тайны, о чем делается отметка в соответствующих лицензиях (при их наличии) обеих договаривающихся сторон. (В редакции Федерального закона от 04.08.2023 № 432-ФЗ)\nВ договоре на проведение совместных и других работ, заключаемом в установленном законом порядке, предусматриваются взаимные обязательства сторон по обеспечению сохранности сведений, составляющих государственную тайну, как в процессе проведения работ, так и по их завершении, а также условия финансирования работ (услуг) по защите сведений, составляющих государственную тайну.\nОрганизация контроля за эффективностью защиты государственной тайны при проведении совместных и других работ возлагается на заказчика этих работ в соответствии с положениями заключенного сторонами договора.\nПри нарушении исполнителем в ходе совместных и других работ взятых на себя обязательств по защите государственной тайны заказчик вправе приостановить выполнение заказа до устранения нарушений, а при повторных нарушениях - поставить вопрос об аннулировании заказа и лицензии на проведение работ с использованием сведений, составляющих государственную тайну, и о привлечении виновных лиц к ответственности. При этом материальный ущерб, нанесенный исполнителем государству в лице заказчика, подлежит взысканию в соответствии с действующим законодательством."],
["18","Передача сведений, составляющих государственную тайну, другим государствам или международным организациям","","2007-12-01","Статья 18. Передача сведений, составляющих государственную тайну, другим государствам или международным организациям\n(Наименование в редакции Федерального закона от 01.12.2007 № 294-ФЗ)\nРешение о передаче сведений, составляющих государственную тайну, другим государствам или международным организациям принимается Правительством Российской Федерации при наличии экспертного заключения межведомственной комиссии по защите государственной тайны о возможности передачи этих сведений. (В редакции Федерального закона от 01.12.2007 № 294-ФЗ)\nОбязательства принимающей стороны по защите передаваемых ей сведений предусматриваются заключаемым с ней договором (соглашением)."],
["19","Защита сведений, составляющих государственную тайну, при изменении функций субъектов правоотношений","","","Статья 19. Защита сведений, составляющих государственную тайну, при изменении функций субъектов правоотношений\nОрганы государственной власти, предприятия, учреждения и организации, располагающие сведениями, составляющими государственную тайну, в случаях изменения их функций, форм собственности, ликвидации или прекращения работ с использованием сведений, составляющих государственную тайну, обязаны принять меры по обеспечению защиты этих сведений и их носителей. При этом носители сведений, составляющих государственную тайну, в установленном порядке уничтожаются, сдаются на архивное хранение либо передаются:\nправопреемнику органа государственной власти, предприятия, учреждения или организации, располагающих сведениями, составляющими государственную тайну, если этот правопреемник имеет полномочия по проведению работ с использованием указанных сведений;\nоргану государственной власти, в распоряжении которого в соответствии со статьей 9 настоящего Закона находятся соответствующие сведения;\nдругому органу государственной власти, предприятию, учреждению или организации по указанию межведомственной комиссии по защите государственной тайны."],
["20","Органы защиты государственной тайны","","2004-06-29","Статья 20. Органы защиты государственной тайны\nК органам защиты государственной тайны относятся:\nмежведомственная комиссия по защите государственной тайны;\nфедеральный орган исполнительной власти, уполномоченный в области обеспечения безопасности, федеральный орган исполнительной власти, уполномоченный в области обороны, федеральный орган исполнительной власти, уполномоченный в области внешней разведки, федеральный орган исполнительной власти, уполномоченный в области противодействия техническим разведкам и технической защиты информации, и их территориальные органы; (В редакции Федерального закона от 29.06.2004 № 58-ФЗ)\nорганы государственной власти, предприятия, учреждения и организации и их структурные подразделения по защите государственной тайны.\nМежведомственная комиссия по защите государственной тайны является коллегиальным органом, координирующим деятельность органов государственной власти по защите государственной тайны в интересах разработки и выполнения государственных программ, нормативных и методических документов, обеспечивающих реализацию законодательства Российской Федерации о государственной тайне. Функции межведомственной комиссии по защите государственной тайны и ее надведомственные полномочия реализуются в соответствии с Положением о межведомственной комиссии по защите государственной тайны, утверждаемым Президентом Российской Федерации.\nФедеральный орган исполнительной власти, уполномоченный в области обеспечения безопасности, федеральный орган исполнительной власти, уполномоченный в области обороны, федеральный орган исполнительной власти, уполномоченный в области внешней разведки, федеральный орган исполнительной власти, уполномоченный в области противодействия техническим разведкам и технической защиты информации, и их территориальные органы организуют и обеспечивают защиту государственной тайны в соответствии с функциями, возложенными на них законодательством Российской Федерации. (В редакции Федерального закона от 29.06.2004 № 58-ФЗ)\nОрганы государственной власти, предприятия, учреждения и организации обеспечивают защиту сведений, составляющих государственную тайну, в соответствии с возложенными на них задачами и в пределах своей компетенции. Ответственность за организацию защиты сведений, составляющих государственную тайну, в органах государственной власти, на предприятиях, в учреждениях и организациях возлагается на их руководителей. В зависимости от объема работ с использованием сведений, составляющих государственную тайну, руководителями органов государственной власти, предприятий, учреждений и организаций создаются структурные подразделения по защите государственной тайны, функции которых определяются указанными руководителями в соответствии с нормативными документами, утверждаемыми Правительством Российской Федерации, и с учетом специфики проводимых ими работ.\nЗащита государственной тайны является видом основной деятельности органа государственной власти, предприятия, учреждения или организации."],
["21","Оформление допуска должностного лица или гражданина к государственной тайне","","2023-08-04","Статья 21. Оформление допуска должностного лица или гражданина к государственной тайне\nОформление допуска должностного лица или гражданина к государственной тайне осуществляется с его согласия и предусматривает:\nпредставление собственноручно заполненной и подписанной им анкеты установленной формы, содержащей сведения о нем и его близких родственниках, к которым для целей настоящего Закона относятся супруг (супруга), отец, мать, дети, в том числе усыновленные, усыновители, полнородные и неполнородные (имеющие общих отца или мать) братья и сестры, а также представление документов, удостоверяющих личность оформляемого лица и подтверждающих указанные в анкете сведения о нем и его близких родственниках;\nпроведение в отношении его полномочными органами проверочных мероприятий в случаях, установленных Правительством Российской Федерации (если иное не установлено Президентом Российской Федерации), в целях выявления оснований, предусмотренных статьей 22 настоящего Закона;\nознакомление его с нормами законодательства Российской Федерации о государственной тайне, предусматривающими ответственность за нарушение указанного законодательства, а также ограничения его прав в соответствии со статьей 24 настоящего Закона;\nпринятие решения руководителем (уполномоченным им должностным лицом) органа государственной власти, органа публичной власти федеральной территории, органа местного самоуправления, предприятия, учреждения или организации о допуске оформляемого лица к государственной тайне.\nВ отношении граждан, призванных на военную службу или военные сборы, представление собственноручно заполненной анкеты установленной формы и получение их согласия на оформление допуска к государственной тайне не являются обязательными.\nВ отношении заместителей руководителей федеральных органов исполнительной власти (за исключением федеральных органов исполнительной власти, уполномоченных в области обеспечения безопасности, обороны, внешней разведки, государственной охраны, мобилизационной подготовки и мобилизации, противодействия техническим разведкам и технической защиты информации, федерального органа исполнительной власти, осуществляющего функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере деятельности войск национальной гвардии Российской Федерации, в сфере оборота оружия, в сфере частной охранной деятельности и в сфере вневедомственной охраны), организаций, наделенных в соответствии с федеральным законом полномочиями осуществлять от имени Российской Федерации государственное управление в установленной сфере деятельности, при наличии у указанных лиц основания для отказа в допуске к государственной тайне решение о допуске оформляемого лица к сведениям, составляющим государственную тайну, принимается межведомственной комиссией по защите государственной тайны в порядке, установленном Президентом Российской Федерации.\nПроверочные мероприятия, связанные с допуском должностных лиц и граждан к государственной тайне, проводятся федеральным органом исполнительной власти, уполномоченным в области обеспечения безопасности, и (или) его территориальными органами.\nПроверочные мероприятия, связанные с допуском к государственной тайне сотрудников и граждан, принимаемых на службу (работу) в федеральный орган исполнительной власти, уполномоченный в области внешней разведки, проводятся указанным федеральным органом исполнительной власти во взаимодействии с федеральным органом исполнительной власти, уполномоченным в области обеспечения безопасности.\nПроверочные мероприятия проводятся в соответствии с законодательством Российской Федерации. Объем проверочных мероприятий зависит от степени секретности сведений, к которым будет допускаться оформляемое лицо.\nУстанавливаются три формы допуска к государственной тайне должностных лиц и граждан, соответствующие трем степеням секретности сведений, составляющих государственную тайну: к сведениям особой важности, совершенно секретным сведениям или секретным сведениям. Наличие у должностных лиц и граждан права на доступ к сведениям более высокой степени секретности является основанием для доступа их к сведениям более низкой степени секретности.\nЗаключение трудового договора (контракта) до окончания проведения проверочных мероприятий, связанных с допуском к государственной тайне, не допускается.\nПредусмотренный настоящей статьей порядок допуска должностных лиц и граждан к государственной тайне в периоды мобилизации, действия чрезвычайного или военного положения может быть изменен Президентом Российской Федерации.\n(Статья в редакции Федерального закона от 04.08.2023 № 432-ФЗ)"],
["21.1","Особый порядок оформления допуска к государственной тайне","","2023-08-04","Статья 21.1. Особый порядок оформления допуска к государственной тайне\nДопуск к государственной тайне в особом порядке оформляется:\nсенаторам Российской Федерации, депутатам Государственной Думы, депутатам законодательных органов субъектов Российской Федерации и судьям - на период исполнения ими своих полномочий в случае необходимости их доступа к сведениям, составляющим государственную тайну;\nдолжностным лицам, замещающим должности, предусмотренные Перечнем должностей, при замещении которых лица считаются допущенными к государственной тайне;\nгражданам Российской Федерации, являющимся адвокатами (за исключением лиц, имеющих гражданство (подданство) иностранного государства, или лиц, включенных в реестр иностранных агентов) и участвующим в судопроизводстве по делам, содержащим сведения, составляющие государственную тайну, - на период их участия в судопроизводстве;\nгражданам Российской Федерации, являющимся участниками уголовного судопроизводства по делам, содержащим сведения, составляющие государственную тайну, и не замещающим должностей, предусматривающих допуск к государственной тайне, на постоянной основе (за исключением экспертов, специалистов и переводчиков, имеющих гражданство (подданство) иностранного государства или включенных в реестр иностранных агентов), - на период их участия в уголовном судопроизводстве в случаях, предусмотренных уголовно-процессуальным законодательством Российской Федерации;\nглавам муниципальных образований, полномочия которых предусматривают доступ к сведениям, составляющим государственную тайну, - на период исполнения ими своих полномочий.\nПеречни муниципальных образований, полномочия глав которых предусматривают доступ к сведениям, составляющим государственную тайну, определяются высшими должностными лицами соответствующих субъектов Российской Федерации.\nОформление допуска лиц, указанных в части первой настоящей статьи, к государственной тайне, за исключением лиц, замещающих должности, предусмотренные Перечнем должностей, при замещении которых лица считаются допущенными к государственной тайне, заключается в ознакомлении их с нормами законодательства Российской Федерации о государственной тайне, предусматривающими ответственность за его нарушение и возможное временное ограничение их права на выезд из Российской Федерации в соответствии с положениями статьи 24 настоящего Закона, о чем у них берется соответствующая подписка.\nПроверочные мероприятия в отношении лиц, допускаемых к государственной тайне в особом порядке, за исключением должностных лиц, замещающих должности, предусмотренные Перечнем должностей, при замещении которых лица считаются допущенными к государственной тайне, не проводятся.\nНеобходимость проведения полномочными органами проверочных мероприятий, предусмотренных статьей 21 настоящего Закона, в отношении лиц, замещающих должности, предусмотренные Перечнем должностей, при замещении которых лица считаются допущенными к государственной тайне, либо претендующих на замещение указанных должностей, определяется Президентом Российской Федерации.\nЛица, замещающие должности, предусмотренные Перечнем должностей, при замещении которых лица считаются допущенными к государственной тайне, имеют право на доступ к сведениям, составляющим государственную тайну, со дня замещения указанных должностей.\n(Дополнение статьей - Федеральный закон от 06.10.1997 № 131-ФЗ) (В редакции Федерального закона от 04.08.2023 № 432-ФЗ)"],
["21.2","Обязанности должностных лиц и граждан Российской Федерации, допущенных к государственной тайне, и социальные гарантии","","2023-08-04","Статья 21.2. Обязанности должностных лиц и граждан Российской Федерации, допущенных к государственной тайне, и социальные гарантии\nДолжностные лица и граждане Российской Федерации, допущенные к государственной тайне, обязаны:\nне разглашать сведения, составляющие государственную тайну, а также выполнять иные требования законодательства Российской Федерации о государственной тайне;\nинформировать в установленном порядке об имеющихся у должностного лица или гражданина Российской Федерации, допущенных к государственной тайне, данных, свидетельствующих о наличии (возникновении) обстоятельств, которые в соответствии со статьей 22 настоящего Закона являются основаниями для отказа в допуске к государственной тайне;\nинформировать в установленном порядке о предпринимавшихся попытках получения от них сведений, составляющих государственную тайну.\nДля должностных лиц и граждан, допущенных к государственной тайне на постоянной основе, устанавливаются следующие социальные гарантии:\nпроцентные надбавки к должностному окладу (тарифной ставке) в зависимости от степени секретности сведений, к которым они имеют доступ;\nпроцентные надбавки к должностному окладу (тарифной ставке) за стаж работы в структурных подразделениях по защите государственной тайны;\nпреимущественное право при прочих равных условиях на оставление на работе при проведении органами государственной власти, органами местного самоуправления, органами публичной власти федеральных территорий, предприятиями, учреждениями и организациями организационных и (или) штатных мероприятий.\n(Дополнение статьей - Федеральный закон от 04.08.2023 № 432-ФЗ)"],
["22","Основания для отказа должностному лицу или гражданину в допуске к государственной тайне","","2023-08-04","Статья 22. Основания для отказа должностному лицу или гражданину в допуске к государственной тайне\nОснованиями для отказа должностному лицу или гражданину в допуске к государственной тайне могут являться:\nпризнание его недееспособным или ограниченно дееспособным на основании решения суда, вступившего в законную силу, наличие у него статуса обвиняемого (подсудимого) по уголовному делу о совершенном по неосторожности преступлении против государственной власти или об умышленном преступлении, наличие у него непогашенной или неснятой судимости за данные преступления, прекращение в отношении его уголовного дела (уголовного преследования) по нереабилитирующим основаниям, если со дня прекращения такого уголовного дела (уголовного преследования) не истек срок, равный сроку давности привлечения к уголовной ответственности за совершение этих преступлений; (В редакции Федерального закона от 29.07.2018 № 256-ФЗ)\nналичие у него медицинских противопоказаний для работы с использованием сведений, составляющих государственную тайну, согласно перечню, утверждаемому федеральным органом исполнительной власти, уполномоченным в области здравоохранения и социального развития; (В редакции Федерального закона от 29.06.2004 № 58-ФЗ)\nпостоянное проживание его самого и (или) его близких родственников за границей и (или) наличие у него и (или) его близких родственников гражданства (подданства) иностранного государства либо вида на жительство или иного документа, подтверждающего право на постоянное проживание гражданина на территории иностранного государства; (В редакции Федерального закона от 04.08.2023 № 432-ФЗ)\nвключение его в реестр иностранных агентов либо выявление в результате проверочных мероприятий действий оформляемого лица, создающих угрозу безопасности Российской Федерации; (В редакции федеральных законов от 30.12.2020 № 481-ФЗ, от 05.12.2022 № 498-ФЗ)\nуклонение его от проверочных мероприятий и (или) сообщение им заведомо ложных анкетных данных;\nнарушение им требований законодательства Российской Федерации о государственной тайне. (Дополнение абзацем - Федеральный закон от 04.08.2023 № 432-ФЗ)\nВ случае выявления в результате проверочных мероприятий, предусмотренных статьей 21 настоящего Закона, действий должностного лица или гражданина, создающих угрозу безопасности Российской Федерации и способных привести к разглашению сведений, составляющих государственную тайну, утрате их носителей либо к утечке таких сведений по техническим каналам, федеральный орган исполнительной власти, уполномоченный в области обеспечения безопасности, и (или) его территориальный орган вправе вынести заключение о нецелесообразности допуска должностного лица или гражданина к государственной тайне. Порядок и условия вынесения указанного заключения, а также заключения, предусмотренного частью первой статьи 23 настоящего Закона, устанавливаются Президентом Российской Федерации. (Дополнение частью - Федеральный закон от 04.08.2023 № 432-ФЗ)\nРешение об отказе должностному лицу или гражданину в допуске к государственной тайне принимается руководителем (уполномоченным им должностным лицом) органа государственной власти, органа публичной власти федеральной территории, органа местного самоуправления, предприятия, учреждения или организации в индивидуальном порядке с учетом результатов проверочных мероприятий. В случае вынесения федеральным органом исполнительной власти, уполномоченным в области обеспечения безопасности, и (или) его территориальным органом заключения о нецелесообразности допуска должностного лица или гражданина к государственной тайне такому должностному лицу или гражданину отказывается в допуске к государственной тайне. Лицо, в отношении которого принято решение об отказе в допуске к государственной тайне, имеет право обжаловать это решение вышестоящему должностному лицу, в вышестоящую организацию или в суд. В отношении заместителей руководителей федеральных органов исполнительной власти (за исключением федеральных органов исполнительной власти, уполномоченных в области обеспечения безопасности, обороны, внешней разведки, государственной охраны, мобилизационной подготовки и мобилизации, противодействия техническим разведкам и технической защиты информации, федерального органа исполнительной власти, осуществляющего функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере деятельности войск национальной гвардии Российской Федерации, в сфере оборота оружия, в сфере частной охранной деятельности и в сфере вневедомственной охраны), организаций, наделенных в соответствии с федеральным законом полномочиями осуществлять от имени Российской Федерации государственное управление в установленной сфере деятельности, решение об отказе в допуске к государственной тайне, в том числе при наличии заключения, указанного в настоящей части, принимается межведомственной комиссией по защите государственной тайны в порядке, установленном Президентом Российской Федерации. (В редакции Федерального закона от 04.08.2023 № 432-ФЗ)"],
["23","Условия прекращения допуска должностного лица или гражданина к государственной тайне","","2023-08-04","Статья 23. Условия прекращения допуска должностного лица или гражданина к государственной тайне\nДопуск должностного лица или гражданина к государственной тайне прекращается по решению руководителя (уполномоченного им должностного лица) органа государственной власти, органа публичной власти федеральной территории, органа местного самоуправления, предприятия, учреждения или организации в случае прекращения исполнения им обязанностей (полномочий), связанных с доступом к сведениям, составляющим государственную тайну, а также в случае вынесения федеральным органом исполнительной власти, уполномоченным в области обеспечения безопасности, и (или) его территориальным органом заключения о нецелесообразности допуска должностного лица или гражданина к государственной тайне.\nДопуск должностного лица или гражданина к государственной тайне, оформленный в соответствии со статьей 21 настоящего Закона, может быть прекращен по решению руководителя (уполномоченного им должностного лица) органа государственной власти, органа публичной власти федеральной территории, органа местного самоуправления, предприятия, учреждения или организации при наличии обстоятельств, являющихся согласно статье 22 настоящего Закона основанием для отказа должностному лицу или гражданину в допуске к государственной тайне.\nВ отношении заместителей руководителей федеральных органов исполнительной власти (за исключением федеральных органов исполнительной власти, уполномоченных в области обеспечения безопасности, обороны, внешней разведки, государственной охраны, мобилизационной подготовки и мобилизации, противодействия техническим разведкам и технической защиты информации, федерального органа исполнительной власти, осуществляющего функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере деятельности войск национальной гвардии Российской Федерации, в сфере оборота оружия, в сфере частной охранной деятельности и в сфере вневедомственной охраны), организаций, наделенных в соответствии с федеральным законом полномочиями осуществлять от имени Российской Федерации государственное управление в установленной сфере деятельности, решение о прекращении допуска к государственной тайне принимается межведомственной комиссией по защите государственной тайны в порядке, установленном Президентом Российской Федерации, при наличии обстоятельств, являющихся согласно статье 22 настоящего Закона основанием для отказа должностному лицу или гражданину в допуске к государственной тайне, и (или) в случае вынесения в отношении их заключения, указанного в части первой настоящей статьи.\nПрекращение допуска должностного лица или гражданина к государственной тайне является основанием для прекращения трудового договора (контракта) с ним, если выполняемая работа требует наличия такого допуска. Решение о прекращении допуска должностного лица или гражданина к государственной тайне может быть обжаловано вышестоящему должностному лицу, в вышестоящую организацию или в суд.\nПрекращение допуска к государственной тайне не освобождает должностное лицо или гражданина от обязанности соблюдать требования законодательства Российской Федерации о государственной тайне.\n(Статья в редакции Федерального закона от 04.08.2023 № 432-ФЗ)"],
["24","Ограничения прав должностного лица или гражданина, допущенных или ранее допускавшихся к государственной тайне","","2023-08-04","Статья 24. Ограничения прав должностного лица или гражданина, допущенных или ранее допускавшихся к государственной тайне\nДолжностное лицо или гражданин, допущенные или ранее допускавшиеся к государственной тайне, могут быть временно ограничены в своих правах. Ограничения могут касаться:\nправа на выезд из Российской Федерации в случаях и на сроки, которые предусмотрены федеральным законом, при условии осведомленности в сведениях особой важности или совершенно секретных сведениях;\nправа на использование открытий и изобретений, содержащих сведения, составляющие государственную тайну;\nправа на неприкосновенность частной жизни на период проведения проверочных мероприятий, предусмотренных статьей 21 настоящего Закона.\n(Статья в редакции Федерального закона от 04.08.2023 № 432-ФЗ)"],
["25","Организация доступа должностного лица или гражданина к сведениям, составляющим государственную тайну","","2023-08-04","Статья 25. Организация доступа должностного лица или гражданина к сведениям, составляющим государственную тайну\nОрганизация доступа должностного лица или гражданина к сведениям, составляющим государственную тайну, возлагается на руководителя соответствующего органа государственной власти, органа публичной власти федеральной территории, органа местного самоуправления, предприятия, учреждения или организации, а обеспечение доступа - на их структурные подразделения по защите государственной тайны.\nРуководитель органа государственной власти, органа публичной власти федеральной территории, органа местного самоуправления, предприятия, учреждения или организации несет персональную ответственность за создание таких условий, при которых должностное лицо или гражданин знакомится только с теми сведениями, составляющими государственную тайну, и в таких объемах, которые необходимы ему для выполнения его должностных (функциональных) обязанностей.\nДоступ должностного лица или гражданина к сведениям, составляющим государственную тайну, осуществляется только при наличии у него оформленного в установленном порядке допуска к государственной тайне.\n(Статья в редакции Федерального закона от 04.08.2023 № 432-ФЗ)"],
["26","Ответственность за нарушение законодательства Российской Федерации о государственной тайне","","1997-10-06","Статья 26. Ответственность за нарушение законодательства Российской Федерации о государственной тайне\nДолжностные лица и граждане, виновные в нарушении законодательства Российской Федерации о государственной тайне, несут уголовную, административную, гражданско-правовую или дисциплинарную ответственность в соответствии с действующим законодательством.\nСоответствующие органы государственной власти и их должностные лица основываются на подготовленных в установленном порядке экспертных заключениях об отнесении незаконно распространенных сведений к сведениям, составляющим государственную тайну. (Дополнение частью - Федеральный закон от 06.10.1997 № 131-ФЗ)\nЗащита прав и законных интересов граждан, органов государственной власти, предприятий, учреждений и организаций в сфере действия настоящего Закона осуществляется в судебном или ином порядке, предусмотренном настоящим Законом."],
["27","Допуск предприятий, учреждений и организаций к проведению работ, связанных с использованием сведений, составляющих государственную тайну","","2023-08-04","Статья 27. Допуск предприятий, учреждений и организаций к проведению работ, связанных с использованием сведений, составляющих государственную тайну\nДопуск предприятий, учреждений и организаций к проведению работ, связанных с использованием сведений, составляющих государственную тайну, созданием средств защиты информации, а также с осуществлением мероприятий и (или) оказанием услуг по защите государственной тайны, осуществляется путем получения ими в порядке, устанавливаемом Правительством Российской Федерации, лицензий на проведение работ со сведениями соответствующей степени секретности.\nЛицензия на проведение указанных работ выдается на основании результатов специальной экспертизы предприятия, учреждения и организации и государственной аттестации их руководителей, ответственных за защиту сведений, составляющих государственную тайну, расходы по проведению которых относятся на счет предприятия, учреждения, организации, получающих лицензию.\nЛицензия на проведение работ с использованием сведений, составляющих государственную тайну, выдается предприятию, учреждению, организации при выполнении ими следующих условий:\nвыполнение требований нормативных документов, утверждаемых Правительством Российской Федерации, по обеспечению защиты сведений, составляющих государственную тайну, в процессе выполнения работ, связанных с использованием указанных сведений;\nналичие в их структуре подразделений по защите государственной тайны и специально подготовленных сотрудников для работы по защите информации, количество и уровень квалификации которых достаточны для обеспечения защиты государственной тайны;\nналичие у них сертифицированных средств защиты информации.\nВ периоды мобилизации, действия чрезвычайного или военного положения Президентом Российской Федерации может быть установлен иной порядок допуска предприятий, учреждений и организаций к проведению работ, связанных с использованием сведений, составляющих государственную тайну. (Дополнение частью - Федеральный закон от 04.08.2023 № 432-ФЗ)"],
["28","Порядок сертификации средств защиты информации","","2011-07-19","Статья 28. Порядок сертификации средств защиты информации\nСредства защиты информации должны иметь сертификат, удостоверяющий их соответствие требованиям по защите сведений соответствующей степени секретности.\nОрганизация сертификации средств защиты информации возлагается на федеральный орган исполнительной власти, уполномоченный в области противодействия техническим разведкам и технической защиты информации, федеральный орган исполнительной власти, уполномоченный в области обеспечения безопасности, и федеральный орган исполнительной власти, уполномоченный в области обороны, в соответствии с функциями, возложенными на них законодательством Российской Федерации. Сертификация осуществляется в соответствии с настоящим Законом в порядке, установленном Правительством Российской Федерации. (В редакции федеральных законов от 06.10.1997 № 131-ФЗ; от 30.06.2003 № 86-ФЗ; от 29.06.2004 № 58-ФЗ; от 19.07.2011 № 248-ФЗ)\nКоординация работ по организации сертификации средств защиты информации возлагается на межведомственную комиссию по защите государственной тайны."],
["29","Финансирование мероприятий по защите государственной тайны","","2004-08-22","Статья 29. Финансирование мероприятий по защите государственной тайны\nФинансирование деятельности органов государственной власти, бюджетных предприятий, учреждений и организаций и их структурных подразделений по защите государственной тайны, а также социальных гарантий, предусмотренных настоящим Законом, осуществляется за счет средств федерального бюджета, средств бюджетов субъектов Российской Федерации и средств местных бюджетов, а остальных предприятий, учреждений и организаций - за счет средств, получаемых от их основной деятельности при выполнении работ, связанных с использованием сведений, составляющих государственную тайну. (В редакции Федерального закона от 22.08.2004 № 122-ФЗ)\nСредства на финансирование государственных программ в области защиты государственной тайны предусматриваются в федеральном бюджете Российской Федерации отдельной строкой.\nКонтроль за расходованием финансовых средств, выделяемых на проведение мероприятий по защите государственной тайны, осуществляется руководителями органов государственной власти, органов местного самоуправления, предприятий, учреждений и организаций, заказчиками работ, а также специально уполномоченными на то представителями Министерства финансов Российской Федерации. Если осуществление этого контроля связано с доступом к сведениям, составляющим государственную тайну, то перечисленные лица должны иметь допуск к сведениям соответствующей степени секретности. (В редакции Федерального закона от 22.08.2004 № 122-ФЗ)"],
["30","Контроль за обеспечением защиты государственной тайны","","1997-10-06","Статья 30. Контроль за обеспечением защиты государственной тайны\nКонтроль за обеспечением защиты государственной тайны осуществляют Президент Российской Федерации, Правительство Российской Федерации в пределах полномочий, определяемых Конституцией Российской Федерации, федеральными конституционными законами и федеральными законами.\n(Статья в редакции Федерального закона от 06.10.1997 № 131-ФЗ)"],
["30.1","Федеральный государственный контроль за обеспечением защиты государственной тайны","","2021-06-11","Статья 30.1. Федеральный государственный контроль за обеспечением защиты государственной тайны\nФедеральный государственный контроль за обеспечением защиты государственной тайны осуществляется уполномоченными федеральными органами исполнительной власти (далее - органы государственного контроля) согласно их компетенции в порядке, установленном Правительством Российской Федерации.\nЧасть. (Утратила силу - Федеральный закон от 11.06.2021 № 170-ФЗ)\nО проведении плановой проверки юридическое лицо уведомляется не позднее трех рабочих дней до ее начала путем направления органом государственного контроля письменного уведомления.\nОснованием для проведения внеплановой выездной проверки является:\nистечение срока исполнения юридическим лицом выданного органом государственного контроля предписания об устранении выявленного нарушения требований законодательства Российской Федерации в области защиты государственной тайны;\nпоступление в органы государственного контроля информации, указывающей на признаки нарушения требований законодательства Российской Федерации о государственной тайне;\nналичие предписания (приказа, распоряжения или иного распорядительного документа) руководителя (уполномоченного им должностного лица) органа государственного контроля о проведении внеплановой проверки, изданного в соответствии с поручением Президента Российской Федерации или Правительства Российской Федерации либо на основании требования прокурора о проведении внеплановой проверки в рамках надзора за исполнением законов по поступившим в органы прокуратуры материалам и обращениям.\nСрок проведения проверки составляет не более чем тридцать рабочих дней со дня начала ее проведения.\nВ исключительных случаях, связанных с необходимостью проведения сложных и (или) длительных исследований, испытаний, специальных экспертиз и расследований на основании мотивированных предложений должностных лиц органа государственного контроля, проводящих проверку, срок проведения проверки может быть продлен руководителем органа государственного контроля (уполномоченным им должностным лицом), но не более чем на двадцать рабочих дней.\nВыездная проверка юридических лиц проводится на основании предписания (приказа, распоряжения или иного распорядительного документа), подписанного руководителем (уполномоченным им должностным лицом) органа государственного контроля.\nВнеплановая выездная проверка, основание проведения которой указано в абзаце третьем части четвертой настоящей статьи, проводится без предварительного уведомления.\nИнформация об организации проверок, проводимых органами государственного контроля, в том числе о планировании, проведении и результатах таких проверок, в органы прокуратуры не направляется.\n(Дополнение статьей - Федеральный закон от 18.07.2011 № 242-ФЗ)"],
["31","Межведомственный и ведомственный контроль","","2011-07-18","Статья 31. Межведомственный и ведомственный контроль\nМежведомственный контроль за обеспечением защиты государственной тайны в органах государственной власти осуществляют федеральный орган исполнительной власти, уполномоченный в области обеспечения безопасности, федеральный орган исполнительной власти, уполномоченный в области обороны, федеральный орган исполнительной власти, уполномоченный в области внешней разведки, федеральный орган исполнительной власти, уполномоченный в области противодействия техническим разведкам и технической защиты информации, и их территориальные органы, на которые эта функция возложена законодательством Российской Федерации. (В редакции федеральных законов от 06.10.1997 № 131-ФЗ; от 30.06.2003 № 86-ФЗ; от 29.06.2004 № 58-ФЗ; от 18.07.2011 № 242-ФЗ)\nОрганы государственной власти, наделенные в соответствии с настоящим Законом полномочиями по распоряжению сведениями, составляющими государственную тайну, обязаны контролировать эффективность защиты этих сведений во всех подчиненных и подведомственных их органах государственной власти, на предприятиях, в учреждениях и организациях, осуществляющих работу с ними.\nКонтроль за обеспечением защиты государственной тайны в Администрации Президента Российской Федерации, в аппаратах палат Федерального Собрания, Правительства Российской Федерации организуется их руководителями. (В редакции Федерального закона от 06.10.1997 № 131-ФЗ)\nКонтроль за обеспечением защиты государственной тайны в судебных органах и органах прокуратуры организуется руководителями этих органов."],
["32","Прокурорский надзор","","","Статья 32. Прокурорский надзор\nНадзор за соблюдением законодательства при обеспечении защиты государственной тайны и законностью принимаемых при этом решений осуществляют Генеральный прокурор Российской Федерации и подчиненные ему прокуроры.\nДоступ лиц, осуществляющих прокурорский надзор, к сведениям, составляющим государственную тайну, осуществляется в соответствии со статьей 25 настоящего Закона.\nПрезидент Российской Федерации Б.Ельцин Москва, Дом Советов России 21 июля 1993 года № 5485-I"]
];
